import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.LongAdder;

public class Main {
    public static void main(String[] args) throws Exception {
        int threads = 8;
        int rounds = 20_000;
        int expected = threads * rounds;

        // 1. get+put 竞态：计数丢失
        Map<String, Integer> nonAtomic = new ConcurrentHashMap<>();
        nonAtomic.put("hits", 0);
        runWorkers(threads, () -> {
            for (int i = 0; i < rounds; i++) {
                Integer old = nonAtomic.get("hits");  // 读到旧值
                nonAtomic.put("hits", old + 1);         // 覆盖并发写入
            }
        });
        System.out.println("get+put result = " + nonAtomic.get("hits") + " / expected = " + expected);

        // 2. LongAdder 修复：精确计数
        ConcurrentHashMap<String, LongAdder> counters = new ConcurrentHashMap<>();
        runWorkers(threads, () -> {
            for (int i = 0; i < rounds; i++) {
                counters.computeIfAbsent("hits", k -> new LongAdder()).increment();
            }
        });
        long safe = counters.get("hits").sum();
        System.out.println("LongAdder result = " + safe + " / expected = " + expected);
        assert safe == expected;

        // 3. null 禁止
        ConcurrentHashMap<String, String> nullCheck = new ConcurrentHashMap<>();
        try {
            nullCheck.put("k", null);
            throw new AssertionError("ConcurrentHashMap should reject null value");
        } catch (NullPointerException e) {
            System.out.println("null value correctly rejected");
        }

        // 4. 弱一致迭代：遍历期间修改不抛异常
        ConcurrentHashMap<Integer, Integer> iterating = new ConcurrentHashMap<>();
        for (int i = 0; i < 4; i++) iterating.put(i, i);
        int visited = 0;
        for (Integer key : iterating.keySet()) {
            visited++;
            if (key < 4) iterating.put(100 + key, key);
        }
        System.out.println("weak iteration: visited=" + visited + ", finalSize=" + iterating.size());
    }

    private static void runWorkers(int n, Runnable task) throws InterruptedException {
        CountDownLatch done = new CountDownLatch(n);
        for (int i = 0; i < n; i++) {
            new Thread(() -> { try { task.run(); } finally { done.countDown(); } }, "w-" + i).start();
        }
        done.await();
    }
}
